function debounce(fn, wait) {
  let timer;
  function wrapped(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = undefined;
      fn.apply(this, args);
    }, wait);
  }
  wrapped.cancel = () => {
    clearTimeout(timer); timer = undefined;
  };
  return wrapped;
}

function throttle(fn, wait) {
  let timer = null, pending = null;
  function flush() {
    if (!pending) { timer = null; return; }
    const [ctx, args] = pending; pending = null;
    timer = setTimeout(flush, wait);
    fn.apply(ctx, args);
  }
  function wrapped(...args) {
    if (timer === null) {
      timer = setTimeout(flush, wait);
      fn.apply(this, args);
    } else pending = [this, args];
  }
  wrapped.cancel = () => {
    clearTimeout(timer); timer = null; pending = null;
  };
  return wrapped;
}

function clone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return seen.get(value);
  let out;
  if (Array.isArray(value)) out = [];
  else if (value instanceof Date) out = new Date(value.getTime());
  else if (value instanceof RegExp) out = new RegExp(value.source, value.flags);
  else if (value instanceof Map) out = new Map();
  else if (value instanceof Set) out = new Set();
  else {
    const proto = Object.getPrototypeOf(value);
    if (proto !== Object.prototype && proto !== null) throw TypeError('unsupported');
    out = Object.create(proto);
  }
  seen.set(value, out);
  if (value instanceof Map) {
    for (const [k,v] of value) out.set(clone(k,seen),clone(v,seen));
  }
  if (value instanceof Set) for (const v of value) out.add(clone(v,seen));
  for (const key of Reflect.ownKeys(value)) {
    const d = Object.getOwnPropertyDescriptor(value,key);
    if ('value' in d) d.value = clone(d.value,seen);
    Object.defineProperty(out,key,d);
  }
  return out;
}

function all(iterable) {
  return new Promise((resolve, reject) => {
    const items = [...iterable]; // 迭代失败由 Promise 构造器转为拒绝
    const out = new Array(items.length);
    let remaining = items.length;
    if (remaining === 0) { resolve([]); return; }
    items.forEach((item, index) => {
      Promise.resolve(item).then(value => {
        out[index] = value;
        if (--remaining === 0) resolve(out);
      }, reject);
    });
  });
}

class Emitter {
  constructor() { this.events = new Map(); }
