class MiniPromise {
  constructor(executor) {
    this.state = 'pending'; this.value = undefined; this.jobs = [];
    let locked = false;
    const resolve = x => {
      if (locked) return; locked = true; this.adopt(x);
    };
    const reject = e => {
      if (locked) return; locked = true; this.settle('rejected', e);
    };
    try { executor(resolve, reject); } catch (e) { reject(e); }
  }
  settle(state, value) {
    if (this.state !== 'pending') return;
    this.state = state; this.value = value;
    for (const job of this.jobs) queueMicrotask(job);
    this.jobs = [];
  }
  adopt(x) {
    if (x === this) { this.settle('rejected', new TypeError('cycle')); return; }
    if (x !== null && (typeof x === 'object' || typeof x === 'function')) {
      let then;
      try { then = x.then; } catch (e) { this.settle('rejected', e); return; }
      if (typeof then === 'function') {
        let called = false;
        try {
          then.call(x,
            y => { if (!called) { called = true; this.adopt(y); } },
            e => { if (!called) { called = true; this.settle('rejected', e); } });
        } catch (e) { if (!called) { called = true; this.settle('rejected', e); } }
        return;
      }
    }
    this.settle('fulfilled', x);
  }
  then(onFulfilled, onRejected) {
    return new MiniPromise((resolve, reject) => {
      const job = () => {
        const handler = this.state === 'fulfilled' ? onFulfilled : onRejected;
        if (typeof handler !== 'function') {
          (this.state === 'fulfilled' ? resolve : reject)(this.value); return;
        }
        try { resolve(handler(this.value)); } catch (e) { reject(e); }
      };
      if (this.state === 'pending') this.jobs.push(job);
      else queueMicrotask(job);
    });
  }
}

async function pool(urls, k, request) {
  if (!Number.isInteger(k) || k < 1) throw RangeError('k');
  let next = 0, stopped = false;
  const out = new Array(urls.length);
  async function worker() {
    while (!stopped && next < urls.length) {
      const i = next++;                    // 同步领取，不会交叉
      try { out[i] = await request(urls[i]); }   // 按下标写入
      catch (e) { stopped = true; throw e; }
    }
  }
  await Promise.all(Array.from({length: Math.min(k, urls.length)}, worker));
  return out;
}

function lru(cap) {
  if (!Number.isInteger(cap) || cap < 1) throw RangeError('cap');
  const m = new Map();
  return {
    get(k) {
      if (!m.has(k)) return;              // 用 has，避免把 0/false 当成未命中
      const v = m.get(k);
      m.delete(k); m.set(k, v);           // 删再插 = 刷新为最近使用
      return v;
    },
    set(k, v) {
      m.delete(k); m.set(k, v);
      if (m.size > cap) m.delete(m.keys().next().value);  // 淘汰最旧的
    },
  };
}

