function traversals(root) {
  const pre = [], mid = [], post = [];
  function visit(n) {
    if (!n) return;
    pre.push(n.val); visit(n.left);
    mid.push(n.val); visit(n.right); post.push(n.val);
  }
  visit(root); return {pre, mid, post};
}
function levels(root) {
  if (!root) return [];
  const q = [root], out = []; let head = 0;
  while (head < q.length) {
    const end = q.length, row = [];
    while (head < end) {
      const n = q[head++]; row.push(n.val);
      if (n.left) q.push(n.left); if (n.right) q.push(n.right);
