async function pool(urls, k, request) {
  if (!Number.isInteger(k) || k < 1) throw RangeError('k');
  let next = 0, stopped = false;
  const out = new Array(urls.length);
  async function worker() {
    while (!stopped && next < urls.length) {
      const i = next++;
      try { out[i] = await request(urls[i]); }
      catch (e) { stopped = true; throw e; }
    }
  }
  await Promise.all(Array.from({length: Math.min(k, urls.length)}, worker));
  return out;
}

function lru(cap) {
  if (!Number.isInteger(cap) || cap < 1) throw RangeError('cap');
  const m = new Map();
  return {
    get(k) { if (!m.has(k)) return; const v = m.get(k); m.delete(k); m.set(k, v); return v; },
    set(k, v) { m.delete(k); m.set(k, v); if (m.size > cap) m.delete(m.keys().next().value); }
  };
}

function moveCheck(id, target, nodes) {
  const seen = new Set();
  for (let p = target; p !== null; p = nodes.get(p).parentId) {
    if (p === id || seen.has(p)) return 'invalid';
    if (!nodes.has(p)) return 'unknown';
    seen.add(p);
  }
  return 'valid';
}

function debounce(fn, wait) {
  let timer;
  function wrapped(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => { timer = undefined; fn.apply(this, args); }, wait);
  }
  wrapped.cancel = () => { clearTimeout(timer); timer = undefined; };
  return wrapped;
}

