function longestUnique(text) {
  const last = new Map();
  let left = 0, right = 0, best = 0;
  for (const ch of text) {
    if (last.has(ch)) left = Math.max(left, last.get(ch) + 1);
    last.set(ch, right);
    best = Math.max(best, right - left + 1);
    right++;
  }
  return best;
}

function lowerBound(a, x) {
  let lo = 0, hi = a.length;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (a[mid] < x) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

function mergeIntervals(input) {
  const sorted = [...input].sort((a, b) => a[0] - b[0]);
  const out = [];
  for (const [start, end] of sorted) {
    const last = out[out.length - 1];
    if (last && start <= last[1]) last[1] = Math.max(last[1], end);
    else out.push([start, end]);
  }
  return out;
}

function levelIds(root) {
  if (!root) return [];
  const queue = [root], levels = [];
  let head = 0;
  while (head < queue.length) {
    const end = queue.length, layer = [];
    while (head < end) {
      const node = queue[head++];
      layer.push(node.id);
      for (const child of node.children ?? []) queue.push(child);
    }
    levels.push(layer);
  }
  return levels;
}

function minCoins(coins, amount) {
  const dp = Array(amount + 1).fill(Infinity);
  dp[0] = 0;
  for (let x = 1; x <= amount; x++) {
    for (const c of coins) if (c <= x) dp[x] = Math.min(dp[x], dp[x - c] + 1);
  }
  return Number.isFinite(dp[amount]) ? dp[amount] : -1;
}

