import { ref, watch } from 'vue';
import { useRoute } from 'vue-router';
const route = useRoute();
const user = ref(null), error = ref(''), loading = ref(false);
let generation = 0;
watch(() => route.params.id, async (id, _, onCleanup) => {
  const mine = ++generation;
  const controller = new AbortController();
  let active = true;
  onCleanup(() => { active = false; controller.abort(); });
  user.value = null; error.value = ''; loading.value = true;
  const current = () => active && mine === generation && id === route.params.id;
  try {
    const r = await fetch('/api/users/' + encodeURIComponent(String(id)), { signal: controller.signal });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const result = await r.json();
    if (current()) user.value = result;
  } catch (e) {
    if (current() && e.name !== 'AbortError') error.value = e.message;
  } finally { if (current()) loading.value = false; }
}, { immediate: true });

