function bindActions(list, removeById) {
  function click(e) {
    if (!(e.target instanceof Element)) return;
    const button = e.target.closest('button[data-action="delete"]');
    if (!button || !list.contains(button) || button.closest('[data-list]') !== list) return;
    if (button.disabled || !button.dataset.id) return;
    removeById(button.dataset.id);
  }
  list.addEventListener('click', click);
  return () => list.removeEventListener('click', click);
}

