async function submit(form, file) {
  const dto = { merchantId: form.merchantId, type: form.type };
  if (form.type === 'serviceProvider') dto.serviceProviderId = form.serviceProviderId;
  const body = new FormData();
  body.append('metadata', JSON.stringify(dto));
  if (file) body.append('attachment', file, file.name);
  const r = await fetch('/api/applications', { method: 'POST', body });
  if (!r.ok) throw new Error('HTTP ' + r.status);
  return r.json();
}

