function createPlayerSlot(create) {
  let generation = 0, current = null;
  function close() {
    generation++;
    current?.dispose();
    current = null;
  }
  return {
    close,
    async open(device) {
      close();
      const mine = generation;
      let player;
      try { player = await create(device); }
      catch (e) { if (mine === generation) throw e; return; }
      if (mine !== generation) { player.dispose(); return; }
      current = player;
    }
  };
}
